import React from "react";
import "./../css/RequestDetails.css";
import {
  FaArrowRight,
  FaTag,
  FaUserCircle,
  FaUser,
  FaPhone,
  FaMobileAlt,
  FaMapMarkerAlt,
  FaMapMarkedAlt,
  FaMicrochip,
  FaShieldAlt,
  FaQuestionCircle,
  FaClock,
  FaLink,
  FaFileAlt,
  FaMoneyBillWave,
  FaTools,
  FaPercentage,
  FaExclamationCircle,
  FaPlus,
  FaComments,
  FaReceipt,
} from "react-icons/fa";

class RequestDetails extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: {
        requestNumber: "1405050027",
        technicianName: "علی عبداللهی",
        customerName: "مخاخری",
        mobile: "09121457004",
        landline: "---",
        province: "تهران",
        address: "شهریار بعدیل بادامک یاسک ۶ امورز",
        deviceType: "ساید",
        brand: "سامسونگ_SAMSUNG",
        deviceProblem: "یخچال گرم و لاستیک",
        visitDate: "1405/05/28",
        description: "",
        status: "تسویه شده",

        totalReceived: "۲۸,۰۰۰,۰۰۰ تومان",
        consumableCost: "۴,۰۰۰,۰۰۰ تومان",
        consumables:
          "لاستیک درب، فیلترها، ترموویزر، سنسور",
        totalWage: "۲۴,۰۰۰,۰۰۰ تومان",
        commission: "۱۲,۰۰۰,۰۰۰ تومان",

        receiptImage:
          "https://via.placeholder.com/300x220?text=Payment+Receipt",

        settlementDescription: "تایید است",

        relatedRequests: [],
      },
    };
  }

  componentDidMount() {
    /*
      بعداً API را اینجا وصل کن.

      مثال:

      const requestId = this.props.match?.params?.id;

      fetch(`/api/requests/${requestId}`)
        .then((response) => response.json())
        .then((data) => {
          this.setState({
            request: data
          });
        });
    */
  }

  handleBack = () => {
    window.history.back();
  };

  handleAddRelatedRequest = () => {
    /*
      بعداً API افزودن درخواست مرتبط اینجا قرار می‌گیرد.
    */
  };

  renderInfo = (icon, title, value, extraClass = "") => {
    const Icon = icon;

    return (
      <div className="request-detail-box">
        <div className="request-detail-icon">
          <Icon />
        </div>

        <div className="request-detail-text">
          <span className="request-detail-title">
            {title}:
          </span>

          <span className={`request-detail-value ${extraClass}`}>
            {value || ""}
          </span>
        </div>
      </div>
    );
  };

  render() {
    const { request } = this.state;

    return (
      <div className="request-details-page container">

        <style>
          {`
          `}
        </style>

        {/* Header */}
        <div className="request-top-bar">
          <button
            type="button"
            className="request-back-btn"
            onClick={this.handleBack}
          >
            <FaArrowRight />
          </button>
          <div className="request-top-icon">
            <FaComments />
          </div>
        </div>

        {/* اطلاعات درخواست */}

        {this.renderInfo(
          FaTag,
          "شماره درخواست",
          request.requestNumber
        )}

        {this.renderInfo(
          FaUserCircle,
          "نام تعمیرکار",
          request.technicianName
        )}

        {this.renderInfo(
          FaUser,
          "نام مشتری",
          request.customerName
        )}

        {this.renderInfo(
          FaPhone,
          "شماره تماس",
          request.mobile
        )}

        {this.renderInfo(
          FaMobileAlt,
          "تلفن ثابت",
          request.landline
        )}

        {this.renderInfo(
          FaMapMarkerAlt,
          "استان",
          request.province
        )}

        {this.renderInfo(
          FaMapMarkedAlt,
          "آدرس",
          request.address
        )}

        {this.renderInfo(
          FaMicrochip,
          "نوع دستگاه",
          request.deviceType
        )}

        {this.renderInfo(
          FaShieldAlt,
          "برند دستگاه",
          request.brand
        )}

        {this.renderInfo(
          FaQuestionCircle,
          "ایراد دستگاه",
          request.deviceProblem
        )}

        {this.renderInfo(
          FaClock,
          "زمان مراجعه",
          request.visitDate
        )}

        {this.renderInfo(
          FaLink,
          "توضیحات",
          request.description
        )}

        {this.renderInfo(
          FaFileAlt,
          "وضعیت",
          request.status,
          "request-status"
        )}

        {/* مالی */}

        {this.renderInfo(
          FaMoneyBillWave,
          "کل دریافتی",
          request.totalReceived
        )}

        {this.renderInfo(
          FaMoneyBillWave,
          "هزینه لوازم مصرفی",
          request.consumableCost
        )}

        {this.renderInfo(
          FaTools,
          "لوازم مصرفی",
          request.consumables
        )}

        {this.renderInfo(
          FaPercentage,
          "کل اجرت",
          request.totalWage
        )}

        {this.renderInfo(
          FaPercentage,
          "پورسانت (50%)",
          request.commission
        )}

        {/* فیش واریزی */}

        <div className="request-detail-box request-receipt-box">

          <div className="request-detail-icon">
            <FaReceipt />
          </div>

          <div className="request-receipt-content">

            <div className="request-receipt-title row">
              <div className="col-3">
                فیش واریزی:
              </div>
              <div className="col-8">
                <img
                  src={request.receiptImage}
                  alt="فیش واریزی"
                  className="request-receipt-image me-4"
                />
              </div>
            </div>
          </div>
        </div>

        {/* توضیحات تایید تسویه */}

        {this.renderInfo(
          FaExclamationCircle,
          "توضیحات تایید تسویه",
          request.settlementDescription
        )}

        {/* درخواست های مرتبط */}

        <div className="related-section">

          <div className="related-title text-center">
            درخواست های مرتبط:
          </div>

          {request.relatedRequests.length === 0 ? (
            <div className="related-empty">

              <div className="related-empty-icon">
                <FaLink />
              </div>

              <div>
                هنوز موردی برای نمایش وجود ندارد.
              </div>

            </div>
          ) : (
            request.relatedRequests.map((item) => (
              <div
                key={item.id}
                className="request-detail-box"
              >
                {item.title}
              </div>
            ))
          )}

          <button
            type="button"
            className="related-add-btn"
            onClick={this.handleAddRelatedRequest}
          >
            <FaPlus className="ms-2" />
            افزودن درخواست مرتبط
          </button>

        </div>

      </div>
    );
  }
}

export default RequestDetails;
